import sys
import hashlib
import subprocess
import os

def compute_hash(command_output):
    return hashlib.sha256(command_output.encode()).hexdigest()

def process_task(line_number, line):
    parts = line.strip().split('|', 1)
    if len(parts) != 2:
        print(f"Error: Invalid task format on line {line_number}", file=sys.stderr)
        sys.exit(2)
    command, expected_hash = parts
    try:
        result = subprocess.run(command, shell=True, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        actual_hash = compute_hash(result.stdout)
        if actual_hash == expected_hash:
            print(f"{line_number}: MATCH")
        else:
            print(f"{line_number}: MISMATCH")
            sys.exit(1)
    except subprocess.CalledProcessError as e:
        print(f"{line_number}: MISMATCH", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python task_verifier.py <task_file>", file=sys.stderr)
        sys.exit(2)

    task_file = sys.argv[1]
    if not os.path.exists(task_file):
        print(f"Error: Task file '{task_file}' does not exist", file=sys.stderr)
        sys.exit(2)

    try:
        with open(task_file, 'r') as f:
            line_number = 1
            for line in f:
                process_task(line_number, line)
                line_number += 1
    except IOError as e:
        print(f"Error reading task file: {e}", file=sys.stderr)
        sys.exit(2)

if __name__ == "__main__":
    main()

import sys
import hashlib
import subprocess
from pathlib import Path

def compute_hash(command_output):
    return hashlib.sha256(command_output.encode('utf-8')).hexdigest()

def process_task(line_number, command, expected_hash):
    try:
        result = subprocess.run(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=False
        )
        actual_hash = compute_hash(result.stdout)
        if actual_hash == expected_hash:
            print(f"{line_number}: MATCH")
            return True
        else:
            print(f"{line_number}: MISMATCH")
            return False
    except Exception as e:
        print(f"{line_number}: MISMATCH", file=sys.stderr)
        return False

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <task_file>", file=sys.stderr)
        sys.exit(2)

    task_file = sys.argv[1]
    try:
        with open(task_file, 'r') as f:
            for line_number, line in enumerate(f, 1):
                parts = line.strip().split('|', 1)
                if len(parts) != 2:
                    print(f"{line_number}: MISMATCH", file=sys.stderr)
                    sys.exit(1)
                command, expected_hash = parts
                if not process_task(line_number, command, expected_hash):
                    sys.exit(1)
        sys.exit(0)
    except IOError:
        print(f"Error: Could not read task file '{task_file}'", file=sys.stderr)
        sys.exit(2)

if __name__ == "__main__":
    main()
